pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound input values to avoid overflow/revert issues
        vm.assume(minSum <= 1e30);
        vm.assume(depositAmount <= 1e30);
        vm.assume(collectAmount <= 1e30);

        // Set up the contract: call SetMinSum, then Initialized so Collect can work
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller and make a deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record total Ether in the contract before Collect: balanceOf(c) + sum of all balances (we only have caller's balance)
        uint256 balanceBefore = address(c).balance; // includes deposit
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 totalBefore = balanceBefore + callerBalanceBefore; // but note: balances are inside contract, so double-count? Wait: total contract value = address(c).balance + sum balances? Actually address(c).balance is the ether held by contract, and balances are just internal accounting, so total value held by contract = address(c).balance. But to capture invariant: after Collect, the sum (contract.balance + total of balances) should not increase. Let's compute properly: totalValueBefore = address(c).balance + callerBalanceBefore (since only caller has nonzero balance). However, after Collect, if success, contract sends ether to caller, reducing contract.balance and reducing balances, so total value stays same. If revert, nothing changes. So we check that total never increases.

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Measure after
        uint256 balanceAfter = address(c).balance;
        uint256 callerBalanceAfter = c.balances(caller);
        uint256 totalAfter = balanceAfter + callerBalanceAfter;

        // Assert: total never increased
        assertTrue(totalAfter <= totalBefore, "Total value in contract increased after Collect");
    }
}

