pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 collectAmount, uint256 minSum) public {
        // Bound inputs
        initialBalance = bound(initialBalance, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 0, initialBalance);
        minSum = bound(minSum, 0, 100 ether);

        // Set up the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund caller
        vm.deal(caller, initialBalance);

        // Deposit
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record balances before collect
        uint256 totalBalBefore = c.balances(caller) + address(c).balance;

        // Try to collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record balances after collect
        uint256 totalBalAfter = c.balances(caller) + address(c).balance;

        // General rule: if collect succeeded, total balance did not decrease (except by gas? but we ignore gas)
        // Actually we need a rule that reference passes and mutant fails.
        // Mutant allows collect when balance < minSum, which could drain more than allowed.
        // Rule: if balance was below minSum, collect should revert.
        if (c.balances(caller) < minSum && collectAmount <= c.balances(caller)) {
            assertTrue(success == false, "Should revert when balance < minSum");
        } else if (collectAmount <= c.balances(caller)) {
            // If collect succeeded, total balance (contract + caller) should not change
            // because it's just transferring eth from contract to caller
            assertTrue(totalBalAfter == totalBalBefore, "Total balance should be conserved on successful collect");
        }
    }
}

