        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();
        uint256 balanceBefore = c.balances(caller);
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));
        uint256 balanceAfter = c.balances(caller);
        // If the caller's balance was initially below MinSum, Collect should never succeed (i.e., balance unchanged or revert)
        if (balanceBefore < minSum) {
            // If Collect didn't revert, then it must have not changed the balance
            if (success) {
                assertTrue(balanceAfter <= balanceBefore, "Balance increased when it shouldn't");
            }
            // If it reverted, balance unchanged
            if (!success) {
                assertTrue(balanceAfter == balanceBefore, "Balance changed after revert");
            }
        }
    }
}

