contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 deposit, uint256 withdraw) public {
        vm.assume(caller != address(0));
        vm.assume(deposit > 0 && deposit <= type(uint128).max);
        vm.assume(withdraw > 0 && withdraw <= deposit);
        vm.assume(minSum <= deposit);

        vm.prank(caller);
        vm.deal(caller, deposit);
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Record state before Collect
        uint256 balBefore = c.balances(caller);
        uint256 ethBefore = address(caller).balance;

        // Call Collect
        vm.prank(caller);
        (bool success) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdraw));

        // Rule: If caller's balance was >= MinSum before the call, then the call must succeed and decrease balance by exactly withdraw
        if (balBefore >= minSum) {
            assertTrue(success, "Collect should succeed when balance >= MinSum");
            assertTrue(c.balances(caller) == balBefore - withdraw, "Balance should decrease by withdraw amount");
        }
