pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address user;

    function setUp() public {
        c = new C();
        user = address(this);
        // Prepare the contract: set MinSum to 0 and initialize
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();
        // Fund the test contract to send value
        vm.deal(user, 1 ether);
    }

    function testFuzz_property(address sender, uint256 deposit, uint256 collect, uint256 extraBalance) public {
        // Constrain sender to be non-zero
        vm.assume(sender != address(0));
        // Bound deposit and collect to avoid overflow (uint256 is fine, but keep reasonable)
        deposit = bound(deposit, 0, 10 ether);
        collect = bound(collect, 0, 10 ether);
        extraBalance = bound(extraBalance, 0, 10 ether);

        // Fund the sender with enough eth
        vm.deal(sender, deposit + extraBalance);

        // Initial deposit
        vm.prank(sender);
        c.Deposit{value: deposit}();

        uint256 balanceBefore = c.balances(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collect));

        if (!success) {
            // If revert, no state change — rule vacuously true
            assertTrue(true);
        } else {
            uint256 balanceAfter = c.balances(sender);
            // The balance must decrease by exactly the collected amount
            assertTrue(balanceAfter == balanceBefore - collect);
        }
    }
