        uint256 newMinSum = minSum + 1;

        // Try to call SetMinSum after Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMinSum));

        // In P (reference), SetMinSum reverts (initialized == true), so success == false.
        // In M (buggy), SetMinSum succeeds, so success == true and MinSum changes.
        // Assert that the call reverted, i.e., the state is protected.
        assertTrue(!success, "SetMinSum should revert after initialization");
