    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        vm.assume(depositAmount > 0 && depositAmount < 1e30);
        vm.assume(collectAmount > 0 && collectAmount < 1e30);

        // Set up: initialize contract, set MinSum to 1 so any balance >= 1 can collect
        vm.prank(address(0xdead));
        c.SetMinSum(1);
        vm.prank(address(0xdead));
        c.SetLogFile(address(0xdead));
        vm.prank(address(0xdead));
        c.Initialized();

        // Deposit some ether
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = address(c).balance;
        uint256 senderBalanceBefore = c.balances(sender);

        // Try to collect
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            // After successful Collect, the invariant should hold:
            // new total balance = old total balance - collectAmount
            // new sender balance = old sender balance - collectAmount
            // But since the bug subtracts msg.value in Deposit, the effect is different.
            // General rule: sum of contract balance + all user balances remains constant after Collect.
            uint256 balanceAfter = address(c).balance;
            uint256 senderBalanceAfter = c.balances(sender);
            // The change in contract balance plus change in sender's balance should be zero (no ether lost/created)
            // Contract balance decreases by collectAmount, sender balance decreases by collectAmount, but ether is transferred out.
            // Actually, the total ether in the system (contract + sender) before and after should be:
            // Before: contractBalance + senderBalance (the sender's ether outside the contract is not tracked)
            // After: contractBalance' + senderBalance' + collectAmount (sent to sender)
            // So: contractBalance + senderBalance = contractBalance' + senderBalance' + collectAmount
            // But we don't have sender's external balance. Instead, check that the sum of contract balance and all tracked balances
            // (only the sender's here) decreased by exactly collectAmount, which is accounted for by the external transfer.
            // Simpler: contractBalanceAfter + c.balances(sender) should equal contractBalanceBefore + c.balances(sender) - collectAmount (since that amount left the system)
            // But c.balances is already updated, so:
            assertTrue(balanceAfter + c.balances(sender) == balanceBefore + senderBalanceBefore - collectAmount, "Invariant broken: ether conservation violated");
        }
    }
}

