        // Fund user with enough ETH
        vm.deal(user, type(uint128).max);
        // Deposit some amount
        vm.prank(user);
        c.Deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(user);
        // Bound collectAmount to be <= balanceBefore to avoid revert
        vm.assume(collectAmount <= balanceBefore);
        // Execute Collect
        vm.prank(user);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        // After Collect, the balance should be exactly balanceBefore - collectAmount (if successful)
        if (ok) {
            assertTrue(c.balances(user) == balanceBefore - collectAmount, "Post-collect balance mismatch");
        } else {
