pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 am) public {
        // Restrict inputs to avoid overflow and ensure meaningful test
        vm.assume(caller != address(0));
        vm.assume(minSum <= type(uint256).max / 2);
        vm.assume(am <= type(uint256).max / 2);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller and deposit some ether via Deposit
        uint256 depositAmt = minSum + am; // ensure enough balance for Collect
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Attempt Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // Rule: After Collect call, the caller's balance in the mapping is unchanged from before
        // The reference C: Collect succeeds only if balances[caller] >= minSum and balances[caller] >= am
        // If it succeeds, it subtracts am. If it fails, it does nothing. Thus balance should be (balanceBefore - (success ? am : 0)).
        // But the buggy version: Deposit always reverts, so the caller's balance never gets updated in the mapping.
        // So the reference always satisfies: c.balances(caller) == balanceBefore - (success ? am : 0).
        uint256 expectedBalance = success ? balanceBefore - am : balanceBefore;
        assertTrue(c.balances(caller) == expectedBalance, "Balance inconsistency after Collect");
    }
}
